def main() -> None:
    batches = (
        (1, 10, CHAPTERS_01_10),
        (11, 20, CHAPTERS_11_20),
    )
    for first, last, chapters in batches:
        payload = {
            "book_id": "vasilij_o_svjatom_duhe",
            "chapters": [
                {
                    "number": number,
                    "test": [q(*item) for item in questions],
                }
                for number, questions in enumerate(chapters, start=first)
            ],
        }
        path = (
            ROOT
            / "content_tests"
            / "drafts"
            / f"vasilij_o_svjatom_duhe_{first:02d}_{last:02d}.json"
        )
        raw = json.dumps(payload, ensure_ascii=False, indent=2) + "\n"
        for source, replacement in REPLACEMENTS.items():
            raw = raw.replace(source, replacement)
        path.write_text(raw, encoding="utf-8")
        print(path.relative_to(ROOT))


if __name__ == "__main__":
    main()
